#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>

static inline __m256i rotl32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

/* 8-way AVX2 ChaCha20 (8 blocks = 512 bytes per iteration) */
static void chacha20_8x(uint8_t *out, const uint8_t *in, size_t len,
                         const uint32_t key[8], const uint32_t counter_nonce[4]) {
    const __m256i s0 = _mm256_set1_epi32(0x61707865);
    const __m256i s1 = _mm256_set1_epi32(0x3320646e);
    const __m256i s2 = _mm256_set1_epi32(0x79622d32);
    const __m256i s3 = _mm256_set1_epi32(0x6b206574);
    __m256i k0 = _mm256_set1_epi32(key[0]);
    __m256i k1 = _mm256_set1_epi32(key[1]);
    __m256i k2 = _mm256_set1_epi32(key[2]);
    __m256i k3 = _mm256_set1_epi32(key[3]);
    __m256i k4 = _mm256_set1_epi32(key[4]);
    __m256i k5 = _mm256_set1_epi32(key[5]);
    __m256i k6 = _mm256_set1_epi32(key[6]);
    __m256i k7 = _mm256_set1_epi32(key[7]);
    __m256i n0 = _mm256_set1_epi32(counter_nonce[1]);
    __m256i n1 = _mm256_set1_epi32(counter_nonce[2]);
    __m256i n2 = _mm256_set1_epi32(counter_nonce[3]);

    uint32_t ctr = counter_nonce[0];
    size_t off = 0;
    while (off + 512 <= len) {
        __m256i c = _mm256_set_epi32(ctr+7, ctr+6, ctr+5, ctr+4, ctr+3, ctr+2, ctr+1, ctr);
        ctr += 8;
        __m256i x0=s0,x1=s1,x2=s2,x3=s3,x4=k0,x5=k1,x6=k2,x7=k3,x8=k4,x9=k5,x10=k6,x11=k7,x12=c,x13=n0,x14=n1,x15=n2;
        for (int r = 0; r < 10; r++) {
            #define QR(a,b,c2,d) a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=rotl32(d,16); \
                                 c2=_mm256_add_epi32(c2,d); b=_mm256_xor_si256(b,c2); b=rotl32(b,12); \
                                 a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=rotl32(d,8); \
                                 c2=_mm256_add_epi32(c2,d); b=_mm256_xor_si256(b,c2); b=rotl32(b,7);
            QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
            QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
            #undef QR
        }
        x0=_mm256_add_epi32(x0,s0); x1=_mm256_add_epi32(x1,s1); x2=_mm256_add_epi32(x2,s2); x3=_mm256_add_epi32(x3,s3);
        x4=_mm256_add_epi32(x4,k0); x5=_mm256_add_epi32(x5,k1); x6=_mm256_add_epi32(x6,k2); x7=_mm256_add_epi32(x7,k3);
        x8=_mm256_add_epi32(x8,k4); x9=_mm256_add_epi32(x9,k5); x10=_mm256_add_epi32(x10,k6); x11=_mm256_add_epi32(x11,k7);
        x12=_mm256_add_epi32(x12,c); x13=_mm256_add_epi32(x13,n0); x14=_mm256_add_epi32(x14,n1); x15=_mm256_add_epi32(x15,n2);

        /* transpose 8x16 (each xi holds word i of 8 blocks) into block-major and xor */
        __m256i *op = (__m256i *)(out + off);
        const __m256i *ip = (const __m256i *)(in + off);
        /* store interleaved: for simplicity store word-major then... let's do a proper transpose.
           Each block is 16 words. We have 16 vectors of 8 lanes. We want output layout:
           block0[16] block1[16] ... no wait, blocks are sequential 64 bytes each.
           Lane j of all 16 vectors = block j's 16 words, but we need them contiguous.
           Transpose approach: extract lane by lane. */
        uint32_t tmp[8][16] __attribute__((aligned(32)));
        _mm256_store_si256((__m256i*)tmp[0], x0); /* wrong layout, do scalar extract */
        /* redo properly */
        uint32_t w[16][8];
        _mm256_storeu_si256((__m256i*)w[0], x0); _mm256_storeu_si256((__m256i*)w[1], x1);
        _mm256_storeu_si256((__m256i*)w[2], x2); _mm256_storeu_si256((__m256i*)w[3], x3);
        _mm256_storeu_si256((__m256i*)w[4], x4); _mm256_storeu_si256((__m256i*)w[5], x5);
        _mm256_storeu_si256((__m256i*)w[6], x6); _mm256_storeu_si256((__m256i*)w[7], x7);
        _mm256_storeu_si256((__m256i*)w[8], x8); _mm256_storeu_si256((__m256i*)w[9], x9);
        _mm256_storeu_si256((__m256i*)w[10], x10); _mm256_storeu_si256((__m256i*)w[11], x11);
        _mm256_storeu_si256((__m256i*)w[12], x12); _mm256_storeu_si256((__m256i*)w[13], x13);
        _mm256_storeu_si256((__m256i*)w[14], x14); _mm256_storeu_si256((__m256i*)w[15], x15);
        uint8_t ks[512];
        for (int lane = 0; lane < 8; lane++) {
            uint32_t *dst = (uint32_t*)(ks + lane*64);
            for (int wi = 0; wi < 16; wi++) dst[wi] = w[wi][lane];
        }
        const __m256i *kp = (const __m256i*)ks;
        for (int i = 0; i < 512/32; i++) {
            op[i] = _mm256_xor_si256(ip[i], kp[i]);
        }
        off += 512;
    }
}

int main() {
    size_t N = 40u*1024*1024;
    uint8_t *in = aligned_alloc(32, N);
    uint8_t *out = aligned_alloc(32, N);
    memset(in, 1, N);
    uint32_t key[8] = {1,2,3,4,5,6,7,8};
    uint32_t cn[4] = {0,9,10,11};
    chacha20_8x(out, in, N, key, cn);
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int iters = 4;
    for (int i = 0; i < iters; i++) chacha20_8x(out, in, N, key, cn);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("8x naive transpose: %.2f ms, %.0f MB/s\n", dt/iters*1000, (N*iters/1e6)/dt);
    /* checksum */
    uint64_t s=0; for (size_t i=0;i<N;i++) s+=out[i];
    printf("sum %llu\n", (unsigned long long)s);
    return 0;
}
EOF
clang -O3 -mavx2 -o "$PWD/tmp/chacha_bench" "$PWD/tmp/chacha_bench.c" && "$PWD/tmp/chacha_bench""}

